from griffe.extensions import Extension
from griffe.docstrings import Docstring
from griffe import load

class AppendCheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_member_loaded(self, member):
        """Called when a member is loaded."""
        if member.is_function:
            if member.docstring:
                member.docstring.value += " [checked]"
            else:
                member.docstring = Docstring(" [checked]")

# Create extension and load package with it
extension = AppendCheckedExtension()
module = load("mypkg", extensions=[extension])

# Verify the extension worked
for name, member in module.members.items():
    if member.is_function and member.docstring:
        print(f"{name}: {member.docstring.value}")
